nPort;											// V208extern Rect deskBounds;												// V208extern int DebugEnabled;											// V208// V209#ifndef LoWord#define LoWord(n) 			((n) & 0xFFFF)#endif// V209#ifndef HiWord#define HiWord(n) 			((unsigned)(n) >> 16)#endif#define IntToFixed(i) 		((Fixed)((i) << 16))#define sgn(n)				((n) > 0 ? 1 : ((n) < 0 ? -1 : 0))/* V100 *//* Toolbox global variables */#define grayRgn (*(RgnHandle *)0x9EE)	/* Gray desktop region, not including menu bar */#define windowList (*(WindowPeek *)0x9D6)	/* z-ordered list of windows, nearest first */extern int DontUpdate;	/* V208, V1.01 If flag is set, then ignore the next window update event */extern int NormalDraw;	/* V208, In DrawSign(), this indicates that we are merely drawing the   */					   	/* score to the screen.											  *//* MemCrashBuf is a hedge against running out of memory.  In SetupRam(), we will allocate MCBufSizebytes, which we will only release if the system tells us we don't have enough memory.  At thistime, MemCrashBuf is released, and an Alert Box warns the user to save & quit.*/#define MCBufSize 30 * 1024extern Ptr MemCrashBuf;		// V208#define displaceLimit	5	/* V1.02 If double click is done, then the two mouse positions must be */							/* within this many pixels.	*/// V210#define NDEBUGLOG 1#ifdef NDEBUGLOG#define Log(message)#else#define Log(message)  DoLog (message, __FILE__, __LINE__);#endifextern char *tname[];	// V208extern int _startTime, _finishTime;	// V208#define TimerStart		_startTime = TickCount();// V211#define TimerDone		{_finishTime = TickCount();\						 Message3( "time to execute = %d.%d seconds",\						 	(_finishTime - _startTime)/60, (_finishTime - _startTime)%60);}#endif